architecture.h4_f:
msg = CBOR{v:1, kuputuhi, whakautu_ki, tukuna_i}
ct = AES-GCM-256-Whakamuna(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/karere {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, kuputuhi, whakautu_ki?, thread_id?, whakahua?, tukuna_i}
ct = AES-GCM-256-Whakamuna(room_key, nonce, pt, aad=hex(room_id))
waea = CBOR{
  v: 1,
  ciphertext: hex(ct), // taurangi roa
  kore: hex(12B),
  Kaituku_pseudo: hex(16 B),
  tukuna_i: unix_ms
}

cryptoWire.h5_f:
waho = CBOR{
  puna_node: hex32,
  ūnga_kaiwhakamahi: int64,
  inner_ciphertext: paita,
  inner_nonce: paita,
  tukuna_i: unix_ms
}
tohu = Ed25519-Waitohu(puna_priv, waho)
POST /federation/tuku { envelope: waho, tohu: hex64 }

auth.h1_f:
POST /api/authentication/register
  { ingoa kaiwhakamahi, kupuhipa, x25519_public_key, display_name, waea?, īmēra?, avatar_emoji }

Whakautu 201 i hangaia:
  { tohu_uru, refresh_token, ingoa_kaiwhakamahi, ingoa kaiwhakamahi, ... }

auth.h3_f:
utu uru_token:
  { sub: user_id, jti: device_id, typ: "uru", exp: inaianei + 15min }
te utu refresh_token:
  { sub: user_id, jti: device_id, momo: "whakahou", exp: inaianei + 30d }

HS256-i hainatia me te 64-paita ngaro o te node mai i .env

auth.h4_f:
register_begin(): wero = rand(32)
                    kōwhiringa = { rp.id, user.id, pubKeyCredParams, wero }
                    kōwhiringa whakahoki

rehita_oti(whakaatutanga):
  manatokohia te oati ki te TPM / Puka Puka Haumaru CA
  toa { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { kore: 128-bit hex, ttl: 60 }
QR utu utu = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/manatoko { kare }
  → taputapu hou kua rehitatia; I hoki mai nga JWT.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Whakamuna(room_key, nonce, CBOR_payload, aad=room_id)

Anga powhiriwhiri: { momo:"m", ruma, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {ingoakōnae, rahi, chunk_size_hint}
            ← {upload_id, chunk_size}
mongamonga PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
whakaoti POST /api/files/resumable/{upload_id}/whakaoti {plain_blake3}
            ← 201 {file_id, url}
TTL i te kore oti: 24 haora

files.h4_f:
whakakāhore_rārangi = {
  "tono/x-dosexec",
  "tono/x-sharedlib",
  "tono/x-mach-rua",
}
mena he makutu.from_buffer(buf[:1024]) kei roto i te rarangi_whakakahore: whakahokia 415

presence.h1_f:
Kaihoko: i te pehi tuatahi → tuku {momo:"t", state:"tīmata"}
         Karekau he tuku mo te 3 s mena ka rereke te ahua
         10 s i muri i te patene whakamutunga → tuku {momo:"t", state:"stop"}
kaiwhiwhi: mutu-aunoa 10 s i muri i te "tīmatanga" whakamutunga mena kaore he "tu" i tae mai

calls.h1_f:
POST /api/waea/{room_id}/timata {ataata, ororongo} → call_id
WS haapurororaa {momo:"c", momo:" powhiri", call_id}
WS pāhotanga {momo:"c", momo:"offer", sdp}
WS pāhotanga {momo:"c", momo:"whakautu", sdp}
WS pāhotanga {momo:"c", momo:"kaitono",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
kōpaki = {
  puna_node : hex32,
  ūnga_kaiwhakamahi : int64,
  inner_ciphertext: paita,
  inner_nonce : paita,
  tukuna_i: unix_ms,
}
sig = Ed25519Sign(puna_priv, CBOR(kopaki))
POST /federation/tuku { envelope, sig }

gossip.h3_f:
panui = {pubkey, endpoint, advertised_at}
sig = Ed25519-Waitohu(pubkey_priv, CBOR(panuitanga))
utu kohukohu: [..., {ad, sig}, ...]

kaiwhiwhi: manatoko tohu ki ad.pubkey → toa ki te pai
taapiri: PoW o te 2^18 te arahi kore i runga i {pubkey, endpoint}

stealth.h2_f:
ClientHello paita = chrome_120_tauira me {
  tupurangi = our random,
  server_name = to tatou ingoa kaihautū (ko ECH-takai ranei),
  session_id = to tatou id wātū,
}
JA4 = t13d_xxxx_xxxx_xxxx (e ōrite ana ki te pūmau Chrome o nāianei)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {ingoa: x.vortexx.sol}
ECH: ClientHello.extensions += whakamuna_sni(pātuhi_iwi_mai_HTTPS_record)
DGA: rohe(t) = base32( SHA256(kakano ∥ YYYY-MM-DD) )[:16] + ".tauira"

push.h4_f:
iOS NSE: didReceive(tono) { wetewete(tono.content.userInfo) }
Android FCM: onMessageReceived(mamaoKarere) { wetemuna(mamaoKarere.raraunga) }
Tukutuku SW: self.addEventListener('pana', e => wetemuna(e.raraunga))

controller.h2_f:
taputapu = sign_tool
tāuru = rākau pūtake, kī/release.key
whakaatu = {
  putanga: "0.1.0",
  hanga_i: unix_ms,
  kōnae: [{ara, sha256, rahi}, ...]
}
sig = Ed25519-Waitohu(release_priv, CBOR(whakakitea))
putanga = INTEGRITY.sig.json = {whakakitea, haina_e: pub_hex, tohu: sig_hex}

bots.h1_f:
hanga: POST /api/bots {ingoawhakamahi, ingoa_whakaatu, waehere}
          → {bot_id, token, pubkey}
oma: i roto i te-tukatuka (coroutine roto node)
      OR waho (poll-roa /api/bots/{id}/whakahōu, tohu-auth'd)
karere: {kuputuhi, waitohu: Ed25519-Waitohu(bot_priv, canonical_msg)}

bots.h2_f:
i runga /timata {
  tuku "Nau mai, {ctx.first_name}"
}
i runga / tāpiri <item> {
  state.list = (state.list or []) + [ctx.args.item]
  tuku "Apitihia: {ctx.args.item}"
}

security.h4_f:
canary.txt (ia rā):
  {rā, tohu: Ed25519-Waitohu(release_priv, rā)}
Ka whakamanahia e te kiritaki → kei te ngaro, kei te muhu ranei ⇒ kua whakapaetia te whakararu

ohorere:
  kaiwhakahaere POST /api/admin/revoke-katoa {take}
  nga panui node {momo:"n", takahanga:"whakatau", take}
  ka horoia e nga kaihoko nga taviri, ka kaha te re-bootstrap

