POST https://fcm.googleapis.com/v1/projects/<project>/messages:send
Whakamanatanga: Kaimau <oauth2_token>
Tinana: {karere: {tohu: <pūrere>, raraunga: {...hiri...}, phi: {collapse_key}}}

federation.h1_f:
envelope = {puna_node, target_user, inner_ct, inner_nonce, sent_at}
sig = Ed25519-Waitohu(puna_priv, CBOR(kopaki))
POST /federation/tuku { envelope, sig}
Ka whakamanahia e B: haina ki nga federations[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  ihirangi, -- tīwae tohu
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
Uiui: SELECT rowid FROM messages_fts WHERE ihirangi MATCH 'foo'

